candidates.raw:
    adcs_quat_t q_hat;
    adcs_quat_t dq;
    adcs_quat_t prod;
    adcs_quat_t next;
    double theta;
    double half;
    double s;
    double wn;

    if ((q == NULL) || (w == NULL) || (out == NULL)) {
        if (out != NULL) {
            *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        }
        return ADCS_E_NULL;
    }

    if ((!adcs_is_finite_vec3(w)) || (!isfinite(dt)) || (dt < 0.0)) {
        *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_RANGE;
    }

    if (adcs_quat_normalize(q, &q_hat) != ADCS_OK) {
        *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_DEGENERATE;
    }

    wn = adcs_vec3_norm(w);
    theta = wn * dt;

    if (theta <= ADCS_EPS_NORM) {
        dq = (adcs_quat_t){1.0, 0.5 * w->x * dt, 0.5 * w->y * dt, 0.5 * w->z * dt};
    } else {
        half = 0.5 * theta;
        s = sin(half) / wn;
        dq = (adcs_quat_t){cos(half), s * w->x, s * w->y, s * w->z};
    }

    prod = adcs_quat_multiply(&dq, &q_hat);

    if (adcs_quat_normalize(&prod, &next) != ADCS_OK) {
        *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_DEGENERATE;
    }

    if (next.w < 0.0) {
        next.w = -next.w;
        next.x = -next.x;
        next.y = -next.y;
        next.z = -next.z;
    }

    *out = next;
    return ADCS_OK;
}

